<script setup lang="ts">
import BusinessStatus from '../components/BusinessStatus.vue';
import {businessRowClass} from '../business-status';
import {ref,computed,onMounted,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {ElMessage,ElMessageBox} from 'element-plus';
import {api,get,message} from '../api';
import {useAuth} from '../stores/auth';
import {label,date,money,ton,download} from '../fulfillment';
import ContractSigningDialog from '../components/ContractSigningDialog.vue';
import ContractPerformanceDetail from '../components/ContractPerformanceDetail.vue';
const route=useRoute(),router=useRouter(),auth=useAuth();
const rows=ref<any[]>([]),confirmations=ref<any[]>([]),detail=ref<any>(),open=ref(false),error=ref(''),busy=ref(false),loading=ref(false),dialog=ref(false),formMode=ref('create');
const form=ref<any>({}),revisionNumber=ref(1),signing=ref(false),readOnly=ref(false),archiveDialog=ref(false),archiveForm=ref<any>({}),formError=ref(''),archiveError=ref(''),selection=ref<any[]>([]);
const stage=computed(()=>route.path.endsWith('archives')?'archives':route.path.endsWith('performance')?'performance':'signing');
const activeTab=ref('PENDING'),counts=ref<any>({}),page=ref(1),pageSize=ref(10),total=ref(0),q=ref(''),name=ref(''),status=ref(''),applied=ref({q:'',name:'',status:''});let request=0;
const latest=computed(()=>detail.value?.revisions.at(-1)),revision=computed(()=>detail.value?.revisions.find((r:any)=>r.number===revisionNumber.value));
const role=computed(()=>detail.value?.traderId===auth.user?.businessEntityId?'TRADER':detail.value?.carrierId===auth.user?.businessEntityId?'CARRIER':'PLATFORM');
const writable=computed(()=>auth.can('contract:write')),detailWritable=computed(()=>writable.value&&!detail.value?.readOnly),activeRevision=computed(()=>revision.value?.id===latest.value?.id);
const performanceLabel=(s:string)=>({WAITING:'待履行',IN_PROGRESS:'履行中',COMPLETED:'履行完成',TERMINATED:'已终止'} as Record<string,string>)[s]||s;
const archiveLabel=(s:string)=>({TRANSPORT:'粮食运输合同',MULTIMODAL:'多式联运合同',TERMINATION:'合同终止资料','5_YEARS':'5 年','10_YEARS':'10 年','30_YEARS':'30 年',PERMANENT:'永久'} as Record<string,string>)[s]||s;
async function load(){const run=++request;loading.value=true;selection.value=[];try{const result=await get('/contracts/workspace',{stage:stage.value,tab:activeTab.value,page:page.value,pageSize:pageSize.value,...applied.value,status:applied.value.status||undefined});if(run!==request)return;rows.value=result.items;counts.value=result.counts;total.value=result.total;error.value='';}catch(e){if(run===request)error.value=message(e);}finally{if(run===request)loading.value=false;}}
function search(){applied.value={q:q.value.trim(),name:name.value.trim(),status:status.value};if(page.value!==1)page.value=1;else load();}
function reset(){q.value='';name.value='';status.value='';search();}
async function inspect(id:string,drawer=true){try{detail.value=await get(`/contracts/${id}`);revisionNumber.value=detail.value.revisions.at(-1).number;open.value=drawer;error.value='';return true;}catch(e){error.value=message(e);return false;}}
async function signRow(row:any){if(await inspect(row.id,false)){readOnly.value=!!detail.value.readOnly;signing.value=true;}}
function previewDocument(){readOnly.value=true;signing.value=true;}
async function afterSigned(){const id=detail.value.id;detail.value=await get(`/contracts/${id}`);await load();}
async function newForm(mode='create'){formMode.value=mode;formError.value='';form.value={confirmationId:String(route.query.confirmationId||''),settlement:'凭运输回单核对后 30 日内结算，运输费用按承运确认执行。',requirements:'按约定地点交接，保存装卸及签收单据。',platformFeeCents:0,expiresAt:new Date(Date.now()+90*86400000).toISOString(),kind:'CHANGE',reason:''};if(mode!=='create')Object.assign(form.value,latest.value.terms,{version:detail.value.version});else{try{confirmations.value=await get('/contracts/confirmations');}catch(e){error.value=message(e);return;}}dialog.value=true;}
async function save(){if(formMode.value==='create'&&!form.value.confirmationId){formError.value='请选择承运确认';return;}if(!form.value.settlement?.trim()||!form.value.requirements?.trim()||!form.value.expiresAt){formError.value='请填写结算约定、作业要求与合同截止时间';return;}busy.value=true;try{let r:any;if(formMode.value==='create'){const {confirmationId,settlement,requirements,platformFeeCents,expiresAt}=form.value;r=await api.post('/contracts',{confirmationId,settlement,requirements,platformFeeCents,expiresAt});}else{const {settlement,requirements,platformFeeCents,expiresAt,kind,reason,version}=form.value;const body={settlement,requirements,platformFeeCents,expiresAt,kind,reason:reason||'更新合同约定',version};r=formMode.value==='edit'?await api.put(`/contracts/${detail.value.id}`,body):await api.post(`/contracts/${detail.value.id}/change`,body);}dialog.value=false;await load();await inspect(r.data.data.id);ElMessage.success('合同草稿已保存');}catch(e){formError.value=message(e);}finally{busy.value=false;}}
async function action(actionName:string){let reason='';if(['return','reject'].includes(actionName)){try{reason=(await ElMessageBox.prompt('请填写原因','合同处理',{inputValidator:v=>v?.trim()?.length>=2||'请至少填写两个字'})).value;}catch{return;}}busy.value=true;try{await api.post(`/contracts/${detail.value.id}/${actionName}`,{version:detail.value.version,...(reason?{reason}: {})});await load();await inspect(detail.value.id);ElMessage.success('合同状态已更新');}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function exportArchive(id:string){const data=await get(`/contracts/${id}/archive`);download(JSON.stringify(data,null,2),`${data.businessNo}-合同档案.json`);}
async function exportSelected(){busy.value=true;try{for(const row of selection.value)await exportArchive(row.id);ElMessage.success('所选合同档案已导出');}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function archiveRow(row:any){if(!await inspect(row.id,false))return;archiveForm.value={version:detail.value.version,directoryNo:'HT-'+new Date().getFullYear(),dossierNo:detail.value.businessNo,classification:detail.value.snapshot.plan?'MULTIMODAL':'TRANSPORT',name:(detail.value.snapshot.grain||'粮食')+'运输合同档案',retention:'10_YEARS',archiveDate:new Date().toISOString()};archiveError.value='';archiveDialog.value=true;}
async function archiveSave(){const f=archiveForm.value;if(['directoryNo','dossierNo','classification','name','retention','archiveDate'].some(k=>!String(f[k]||'').trim())){archiveError.value='请完整填写归档信息';return;}busy.value=true;try{await api.post(`/contracts/${detail.value.id}/archive`,f);archiveDialog.value=false;activeTab.value='ARCHIVED';page.value=1;await load();ElMessage.success('合同已归档至本企业档案');}catch(e){archiveError.value=message(e);}finally{busy.value=false;}}
async function refreshDetail(){if(detail.value)await inspect(detail.value.id);}
watch([page,pageSize,activeTab],()=>load());
watch(()=>route.path,()=>{open.value=false;signing.value=false;archiveDialog.value=false;activeTab.value='PENDING';page.value=1;q.value='';name.value='';status.value='';applied.value={q:'',name:'',status:''};load();});
onMounted(async()=>{await load();if(route.query.confirmationId){const existing=(await get<any[]>('/contracts')).find(r=>r.confirmationId===route.query.confirmationId);if(existing)await inspect(existing.id);else await newForm();}if(route.query.id)await inspect(String(route.query.id));});
</script>
<template><div v-if="stage==='signing'" class="page-actions"><el-button v-if="auth.user?.businessEntity.type==='TRADER'&&writable" type="primary" @click="newForm()">生成合同包</el-button></div><div v-if="stage!=='performance'" class="contract-stage-tabs"><el-tabs v-model="activeTab"><el-tab-pane :label="`${stage==='signing'?'待签署':'待归档'} (${counts.PENDING||0})`" name="PENDING"/><el-tab-pane :label="`${stage==='signing'?'已签署':'已归档'} (${counts[stage==='signing'?'SIGNED':'ARCHIVED']||0})`" :name="stage==='signing'?'SIGNED':'ARCHIVED'"/></el-tabs><span v-if="stage==='signing'" class="stage-note">已签署按本企业签署情况分类</span></div><el-alert v-if="error" :title="error" type="error" class="form-error" :closable="false"/><div class="filter-panel"><el-form inline @submit.prevent="search"><el-form-item label="合同编号"><el-input v-model="q" clearable placeholder="编号 / 企业 / 地点" @keyup.enter="search"/></el-form-item><el-form-item label="合同名称"><el-input v-model="name" clearable placeholder="输入合同名称" @keyup.enter="search"/></el-form-item><el-form-item label="合同状态"><el-select v-model="status" clearable placeholder="全部状态"><el-option v-for="s in (stage==='signing'?['DRAFT','REVIEW','SIGNING','EFFECTIVE','REJECTED','TERMINATED']:['DRAFT','EFFECTIVE','TERMINATED'])" :key="s" :label="label(s)" :value="s"/></el-select></el-form-item><el-form-item class="filter-actions"><el-button type="primary" plain @click="search">搜索</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form></div><div class="table-panel" v-loading="loading"><div class="list-toolbar"><strong>{{stage==='signing'?'合同签署':stage==='performance'?'合同履行':'合同归档'}} <b>{{total}}</b></strong><div class="toolbar-buttons"><el-button v-if="selection.length" :loading="busy" @click="exportSelected">导出所选 ({{selection.length}})</el-button></div></div><div v-if="selection.length" class="selection-bar">已选择 {{selection.length}} 项<el-button link type="primary" @click="selection=[];load()">清空</el-button></div><el-table :row-class-name="({row}:any)=>businessRowClass({row:{status:stage==='performance'?row.progress.performanceStatus:row.status}})" :data="rows" @selection-change="(v:any[])=>selection=v" @row-dblclick="(r:any)=>inspect(r.id)"><el-table-column type="selection" width="45"/><el-table-column type="index" label="序号" width="62" :index="(index:number)=>(page-1)*pageSize+index+1"/><el-table-column label="合同编号 / 名称" min-width="235"><template #default="{row}"><el-button class="business-number" link type="primary" @click="inspect(row.id)">{{row.businessNo}}</el-button><small class="cell-note">{{row.contractName}}</small></template></el-table-column><el-table-column label="甲方 / 乙方" min-width="220"><template #default="{row}">{{row.snapshot.trader.name}}<small class="cell-note">{{row.snapshot.carrier.name}}</small></template></el-table-column><el-table-column label="合同文件" width="110"><template #default="{row}"><el-button link type="primary" @click="inspect(row.id,false).then(ok=>{if(ok)previewDocument()})">预览文件</el-button><small class="cell-note">主合同 + 附加合同</small></template></el-table-column><el-table-column label="运输总价" width="135"><template #default="{row}">{{money(row.totalCents)}}<small class="cell-note">{{ton(row.quantityKg)}}</small></template></el-table-column><el-table-column v-if="stage==='performance'" label="付款 / 运输进度" width="170"><template #default="{row}"><span class="table-progress-label">付款 {{row.progress.paymentPercent}}%</span><el-progress :percentage="row.progress.paymentPercent" :show-text="false" :stroke-width="5"/><small class="cell-note">交付 {{Math.min(100,Math.round(row.progress.completed/row.quantityKg*100))}}%</small></template></el-table-column><el-table-column :label="stage==='performance'?'履约状态':'合同状态'" width="145"><template #default="{row}"><BusinessStatus :status="stage==='performance'?row.progress.performanceStatus:row.status" :label="stage==='performance'?performanceLabel(row.progress.performanceStatus):stage==='signing'&&row.ownSigned&&row.status==='SIGNING'?'待其他方签署':label(row.status)"/><small class="cell-note">{{row.readOnly?'资料待核验 · 合同草稿':'第 '+row.revisions.at(-1).number+' 版 · '+label(row.revisions.at(-1).kind)}}</small></template></el-table-column><el-table-column :label="stage==='archives'&&activeTab==='ARCHIVED'?'归档时间':'申请时间'" width="170"><template #default="{row}">{{date(row.archiveRecord?.archivedAt||row.createdAt)}}</template></el-table-column><el-table-column label="操作" :width="stage==='archives'?150:140" fixed="right"><template #default="{row}"><el-button v-if="stage==='signing'&&row.revisions.at(-1).status==='SIGNING'&&!row.ownSigned&&writable&&!row.readOnly" link type="primary" @click="signRow(row)">签署</el-button><el-tooltip v-if="stage==='archives'&&!row.archiveRecord&&writable&&!row.readOnly" :content="row.progress.archiveReasons.join('；')||'归档本企业合同'" :disabled="row.progress.canArchive"><span><el-button link type="primary" :disabled="!row.progress.canArchive" @click="archiveRow(row)">归档</el-button></span></el-tooltip><el-button link type="primary" @click="inspect(row.id)">详情</el-button></template></el-table-column></el-table><el-empty v-if="!error&&!loading&&!rows.length" :description="applied.q||applied.name||applied.status?'未找到符合条件的合同':stage==='signing'?(activeTab==='SIGNED'?'暂无已签署合同':'暂无待签署合同'):stage==='performance'?'暂无合同履约资料':activeTab==='ARCHIVED'?'暂无已归档合同':'暂无待归档合同'"/><div class="pagination"><span>共 {{total}} 条记录</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" :page-sizes="[10,20,50]" layout="sizes,prev,pager,next,jumper"/></div></div>
<el-drawer v-model="open" :title="`${stage==='performance'?'合同履约详情':stage==='archives'?'合同档案详情':'合同详情'} · ${detail?.businessNo||''}`" size="1100px"><template v-if="detail"><el-alert v-if="detail.readOnly" title="履约与档案资料待核验，付款及收款仅按计划展示；正式签署与原始凭证待补充。" type="info" :closable="false" class="form-error"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-descriptions :column="2" border class="contract-meta"><el-descriptions-item label="合同名称">{{detail.snapshot.grain||'粮食'}}运输合同</el-descriptions-item><el-descriptions-item label="合同状态"><BusinessStatus :status="detail.status" :label="label(detail.status)"/></el-descriptions-item><el-descriptions-item label="甲方（贸易方）">{{detail.snapshot.trader.name}}</el-descriptions-item><el-descriptions-item label="乙方（承运方）">{{detail.snapshot.carrier.name}}</el-descriptions-item><el-descriptions-item label="运输路线" :span="2">{{detail.snapshot.origin}} → {{detail.snapshot.destination}}</el-descriptions-item></el-descriptions><div class="contract-actions"><el-select v-model="revisionNumber" aria-label="合同版本" style="width:245px"><el-option v-for="r in detail.revisions" :key="r.id" :value="r.number" :label="`第 ${r.number} 版 · ${label(r.kind)} · ${label(r.status)}`"/></el-select><el-button @click="previewDocument">查看合同文件</el-button><el-button @click="exportArchive(detail.id).catch(e=>error=message(e))">导出档案</el-button><el-button @click="refreshDetail">刷新详情</el-button><el-button v-if="detail.status==='EFFECTIVE'&&role==='CARRIER'&&!detail.business" type="primary" @click="router.push({path:'/services',query:{packageId:detail.id}})">查看联运服务</el-button></div><div v-if="stage==='archives'" class="archive-info"><h3>{{detail.archiveRecord?(detail.archiveRecord.referenceOnly?'过程资料归档 · 待核验':'归档信息'):'归档检查'}}</h3><el-descriptions v-if="detail.archiveRecord" :column="2" border><el-descriptions-item label="目录号">{{detail.archiveRecord.directoryNo}}</el-descriptions-item><el-descriptions-item label="案卷号">{{detail.archiveRecord.dossierNo}}</el-descriptions-item><el-descriptions-item label="档案分类">{{archiveLabel(detail.archiveRecord.classification)}}</el-descriptions-item><el-descriptions-item label="档案名称">{{detail.archiveRecord.name}}</el-descriptions-item><el-descriptions-item label="保存期限">{{archiveLabel(detail.archiveRecord.retention)}}</el-descriptions-item><el-descriptions-item label="归档日期">{{date(detail.archiveRecord.archiveDate)}}</el-descriptions-item></el-descriptions><template v-else><el-alert v-if="!detail.progress.canArchive" :title="detail.progress.archiveReasons.join('；')" type="warning" :closable="false"/><el-button v-else-if="detailWritable" type="primary" @click="archiveRow(detail)">归档合同</el-button></template></div><ContractPerformanceDetail v-if="stage!=='signing'" :contract="detail"/><template v-else><div class="contract-summary"><div><span>运输数量</span><strong>{{ton(detail.quantityKg)}}</strong></div><div><span>运输总价</span><strong>{{money(detail.totalCents)}}</strong></div><div><span>合同截止时间</span><strong class="expiry-value">{{date(revision?.terms.expiresAt)}}</strong></div></div><p v-if="revision?.reason" class="revision-reason">处理原因：{{revision.reason}}</p><div class="contract-document-list"><article v-for="doc in revision?.documents" :key="doc.type"><div><strong>{{label(doc.type)}}</strong><small>{{doc.name}}</small></div><div class="document-parties-summary"><el-tag v-for="party in (doc.type==='ADDENDUM'&&revision?.mode==='B'?['TRADER','CARRIER','PLATFORM']:['TRADER','CARRIER'])" :key="party" :type="revision.signatures.some((s:any)=>s.role===party&&s.documentType===doc.type)?'success':'info'">{{label(party)}} · {{revision.signatures.some((s:any)=>s.role===party&&s.documentType===doc.type)?'已签署':'待签署'}}</el-tag></div></article></div><el-button v-if="detailWritable&&activeRevision&&revision?.status==='SIGNING'&&(role!=='PLATFORM'||revision.mode==='B')" type="primary" @click="readOnly=false;signing=true">进入签署页</el-button></template><div v-if="detailWritable&&activeRevision&&!detail.archiveRecord" class="contract-actions lifecycle-actions"><el-button v-if="role==='TRADER'&&latest.status==='REJECTED'" @click="action('revise')">重新起草新版本</el-button><template v-if="role==='TRADER'&&latest.status==='DRAFT'"><el-button @click="newForm('edit')">编辑草稿</el-button><el-button type="primary" :loading="busy" @click="action('submit')">提交承运方确认</el-button></template><template v-if="role==='CARRIER'&&latest.status==='REVIEW'"><el-button @click="action('return')">退回修改</el-button><el-button type="primary" :loading="busy" @click="action('approve')">确认并进入签署</el-button></template><el-button v-if="role==='TRADER'&&['REVIEW','SIGNING'].includes(latest.status)&&!latest.signatures.length" @click="action('withdraw')">撤回</el-button><el-button v-if="role!=='PLATFORM'&&['REVIEW','SIGNING'].includes(latest.status)" @click="action('reject')">拒签</el-button><el-button v-if="role!=='PLATFORM'&&detail.status==='EFFECTIVE'&&['EFFECTIVE','REJECTED'].includes(latest.status)" @click="newForm('change')">发起变更 / 终止</el-button></div></template></el-drawer>
<ContractSigningDialog v-model="signing" :contract="detail" :read-only="readOnly" :revision-number="revisionNumber" @signed="afterSigned"/>
<el-dialog v-model="dialog" :title="formMode==='create'?'生成合同包':formMode==='edit'?'编辑合同草稿':'发起合同变更'" width="650px" :close-on-click-modal="false" destroy-on-close><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><el-form-item v-if="formMode==='create'" label="承运确认" required><el-select v-model="form.confirmationId" filterable style="width:100%"><el-option v-for="c in confirmations" :key="c.id" :value="c.id" :label="`${c.businessNo} · ${ton(c.quantityKg)} · ${money(c.totalCents)}`"/></el-select></el-form-item><el-form-item v-if="formMode==='change'" label="协议类型"><el-radio-group v-model="form.kind"><el-radio value="CHANGE">条款变更</el-radio><el-radio value="TERMINATION">协商终止</el-radio></el-radio-group></el-form-item><el-form-item v-if="formMode!=='create'" label="修改原因"><el-input v-model="form.reason"/></el-form-item><el-form-item label="结算约定" required><el-input v-model="form.settlement" type="textarea" :rows="3"/></el-form-item><el-form-item label="作业及单据要求" required><el-input v-model="form.requirements" type="textarea" :rows="3"/></el-form-item><div class="form-grid"><el-form-item label="平台费用（元）"><el-input-number :model-value="form.platformFeeCents/100" @update:model-value="(v:number|undefined)=>form.platformFeeCents=Math.round((v||0)*100)" :min="0" :max="1000000" :precision="2"/></el-form-item><el-form-item label="合同截止时间" required><el-date-picker v-model="form.expiresAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ"/></el-form-item></div><p class="muted">数量、运输总价与线路来自承运确认，变更草稿会保留原始合同。</p></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存草稿</el-button></template></el-dialog>
<el-dialog v-model="archiveDialog" title="归档合同" width="730px" :close-on-click-modal="false" destroy-on-close><el-alert v-if="archiveError" :title="archiveError" type="error" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item label="目录号" required><el-input v-model="archiveForm.directoryNo" maxlength="60" placeholder="请输入目录号"/></el-form-item><el-form-item label="案卷号" required><el-input v-model="archiveForm.dossierNo" maxlength="60" placeholder="请输入案卷号"/></el-form-item><el-form-item label="档案分类" required><el-select v-model="archiveForm.classification"><el-option v-for="s in ['TRANSPORT','MULTIMODAL','TERMINATION']" :key="s" :value="s" :label="archiveLabel(s)"/></el-select></el-form-item><el-form-item label="档案名称" required><el-input v-model="archiveForm.name" maxlength="100"/></el-form-item><el-form-item label="保存期限" required><el-select v-model="archiveForm.retention"><el-option v-for="s in ['5_YEARS','10_YEARS','30_YEARS','PERMANENT']" :key="s" :value="s" :label="archiveLabel(s)"/></el-select></el-form-item><el-form-item label="归档日期" required><el-date-picker v-model="archiveForm.archiveDate" type="datetime" :disabled-date="(d:Date)=>d.getTime()>Date.now()" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ"/></el-form-item></div><p class="muted">归档保存本企业的合同、签署记录和履约快照。归档后合同内容保持固定。</p></el-form><template #footer><el-button @click="archiveDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="archiveSave">确认归档</el-button></template></el-dialog></template>
<style scoped>.contract-stage-tabs{position:relative;background:white;border:1px solid var(--border);border-radius:7px;padding:0 24px;margin-bottom:20px}.contract-stage-tabs :deep(.el-tabs__header){margin:0}.contract-stage-tabs :deep(.el-tabs__nav-wrap:after){height:0}.contract-stage-tabs :deep(.el-tabs__item){height:54px;padding:0 24px}.stage-note{position:absolute;right:24px;top:20px;font-size:11px;color:#969eaa}.toolbar-buttons{display:flex;gap:16px;align-items:center}.selection-bar{display:flex;align-items:center;gap:20px;padding:12px 16px;background:#fff5f5;margin-bottom:15px;font-size:12px;color:#a15b60;border-radius:5px}.table-progress-label{font-size:12px;color:#717c8b;display:block;margin-bottom:8px}.contract-meta{margin-bottom:20px}.contract-summary{display:grid;grid-template-columns:1fr 1fr 1.3fr;gap:20px;padding:24px;background:#f7f8fa;border-radius:7px;font-size:12px}.contract-summary span{color:#919aa6}.contract-summary strong{display:block;font-size:22px;margin-top:12px}.contract-summary .expiry-value{font-size:16px;line-height:1.7}.contract-actions{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0}.contract-document-list{margin:22px 0;border:1px solid #e5e8ed;border-radius:6px}.contract-document-list article{display:flex;justify-content:space-between;gap:20px;padding:24px}.contract-document-list article+article{border-top:1px solid #edf0f3}.contract-document-list strong{font-size:14px}.contract-document-list small{display:block;color:#9099a6;font-size:12px;margin-top:10px}.document-parties-summary{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.revision-reason{font-size:12px;color:#b77579;margin-top:20px}.archive-info{margin-top:28px}.archive-info h3{font-size:14px;margin-bottom:20px}.lifecycle-actions{padding-top:20px;border-top:1px solid #eef0f3}@media(max-width:800px){.stage-note{display:none}.contract-summary{grid-template-columns:1fr;gap:15px}.contract-summary strong{font-size:18px}.contract-document-list article{flex-direction:column}}
</style>
